#!/usr/bin/env node
/**
 * Urban-Offline Quality Audit System
 * 
 * Comprehensive automated checks for:
 * - Design system compliance
 * - Performance budgets
 * - Colour consistency
 * - Native feel verification
 * - Accessibility standards
 * 
 * Usage: node scripts/quality-audit.js [options]
 * Options:
 *   --strict     Fail on warnings (CI mode)
 *   --fix        Auto-fix where possible
 *   --report     Generate HTML report
 */

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

// ============================================================================
// CONFIGURATION
// ============================================================================

const CONFIG = {
  // Performance budgets
  budgets: {
    initialBundle: 200 * 1024,      // 200KB
    aiModule: 150 * 1024,           // 150KB
    mapModule: 100 * 1024,          // 100KB
    totalRuntime: 2 * 1024 * 1024,  // 2MB
  },
  
  // Colour palette (must match DESIGN_SYSTEM.md)
  colours: {
    primary: ['#f8fafc', '#f1f5f9', '#e2e8f0', '#cbd5e1', '#94a3b8', 
              '#64748b', '#475569', '#334155', '#1e293b', '#0f172a', '#020617'],
    secondary: ['#6366f1', '#4f46e5'],
    emergency: ['#dc4446', '#b91c1c'],
    success: ['#16a34a', '#15803d'],
    warning: ['#d97706', '#b45309'],
    premium: ['#d4a574', '#e8c9a8', '#b8935f'],
  },
  
  // Required CSS variables
  requiredCssVars: [
    '--color-primary-500',
    '--color-primary-600',
    '--color-primary-900',
    '--color-emergency-500',
    '--color-success-500',
    '--color-warning-500',
    '--glass-bg',
    '--glass-border',
    '--duration-fast',
    '--ease-ios-spring',
  ],
  
  // Forbidden patterns
  forbiddenPatterns: [
    { pattern: /gradient.*button/i, message: 'Gradients on buttons not allowed' },
    { pattern: /box-shadow.*border/i, message: 'Mixing shadow and border for depth' },
    { pattern: /color:\s*red/i, message: 'Use --color-emergency-500 instead of red' },
    { pattern: /!important.*color/i, message: 'Avoid !important on colours' },
    { pattern: /width:\s*\d+px.*height:\s*\d+px.*transition.*width/i, 
      message: 'Animating layout properties (use transform instead)' },
  ],
  
  // Required files
  requiredFiles: [
    'src/styles/colors.css',
    'src/styles/design-system.css',
    'src/styles/premium-theme.css',
    'DESIGN_SYSTEM.md',
    'VISION.md',
  ],
};

// ============================================================================
// AUDIT RESULTS
// ============================================================================

class AuditResults {
  constructor() {
    this.errors = [];
    this.warnings = [];
    this.fixed = [];
    this.passed = [];
  }
  
  error(message, file, line) {
    this.errors.push({ message, file, line, severity: 'error' });
    console.error(`❌ ERROR: ${message}${file ? ` in ${file}${line ? `:${line}` : ''}` : ''}`);
  }
  
  warn(message, file, line) {
    this.warnings.push({ message, file, line, severity: 'warning' });
    console.warn(`⚠️  WARNING: ${message}${file ? ` in ${file}${line ? `:${line}` : ''}` : ''}`);
  }
  
  fix(message, file) {
    this.fixed.push({ message, file });
    console.log(`🔧 FIXED: ${message}${file ? ` in ${file}` : ''}`);
  }
  
  pass(message) {
    this.passed.push(message);
    console.log(`✅ PASS: ${message}`);
  }
  
  summary() {
    const total = this.errors.length + this.warnings.length + this.passed.length;
    console.log('\n' + '='.repeat(60));
    console.log('AUDIT SUMMARY');
    console.log('='.repeat(60));
    console.log(`✅ Passed:  ${this.passed.length}`);
    console.log(`⚠️  Warnings: ${this.warnings.length}`);
    console.log(`❌ Errors:   ${this.errors.length}`);
    if (this.fixed.length > 0) {
      console.log(`🔧 Fixed:    ${this.fixed.length}`);
    }
    console.log('-'.repeat(60));
    console.log(`Total checks: ${total}`);
    console.log('='.repeat(60));
    
    return {
      success: this.errors.length === 0,
      errors: this.errors.length,
      warnings: this.warnings.length,
      passed: this.passed.length,
    };
  }
}

const results = new AuditResults();

// ============================================================================
// AUDIT CHECKS
// ============================================================================

/**
 * Check required files exist
 */
function checkRequiredFiles() {
  console.log('\n📁 Checking required files...');
  
  CONFIG.requiredFiles.forEach(file => {
    const fullPath = path.join(process.cwd(), file);
    if (fs.existsSync(fullPath)) {
      results.pass(`Required file exists: ${file}`);
    } else {
      results.error(`Missing required file: ${file}`);
    }
  });
}

